import axios from 'axios';

// Configure axios with base URL
const API_BASE_URL = 'http://127.0.0.1:8000';

const api = axios.create({
  baseURL: API_BASE_URL,
  timeout: 30000, // 30 seconds timeout
  headers: {
    'Content-Type': 'application/json',
  },
});

// Request interceptor for logging
api.interceptors.request.use(
  (config) => {
    console.log(`Making ${config.method?.toUpperCase()} request to ${config.url}`);
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor for error handling
api.interceptors.response.use(
  (response) => {
    return response;
  },
  (error) => {
    console.error('API Error:', error.response?.data || error.message);
    return Promise.reject(error);
  }
);

// API functions
export const uploadLogs = async (loginLogsFile, fileAccessLogsFile) => {
  const formData = new FormData();
  formData.append('login_file', loginLogsFile);
  formData.append('filelog_file', fileAccessLogsFile);
  
  const response = await api.post('/upload/', formData, {
    headers: {
      'Content-Type': 'multipart/form-data',
    },
  });
  return response.data;
};

export const runDetectionPipeline = async () => {
  const response = await api.post('/process/');
  return response.data;
};

export const getBreachEvents = async () => {
  try {
    const response = await api.get('/breach-events/');
    return response.data;
  } catch (error) {
    console.error('Error fetching breach events:', error);
    throw new Error(`Failed to fetch breach events: ${error.response?.status || error.message}`);
  }
};

export const registerFileForMonitoring = async (filePath) => {
  try {
    const response = await api.post('/register-file/', {
      file_path: filePath
    });
    return response.data;
  } catch (error) {
    console.error('Error registering file:', error);
    throw new Error(`Failed to register file: ${error.response?.status || error.message}`);
  }
};

export const checkFileTampering = async () => {
  try {
    const response = await api.get('/tamper-check/');
    return response.data;
  } catch (error) {
    console.error('Error checking file tampering:', error);
    throw new Error(`Failed to check tampering: ${error.response?.status || error.message}`);
  }
};

// Download functions - using direct window.open for better UX
export const downloadBreachEventsCSV = async () => {
  try {
    // Use window.open for direct download instead of fetch
    window.open(`${API_BASE_URL}/download/breach-events`, '_blank');
    return { success: true };
  } catch (error) {
    console.error('Error downloading breach events:', error);
    throw new Error(`Failed to download breach events: ${error.message}`);
  }
};

export const downloadTamperedFilesCSV = async () => {
  try {
    // Use window.open for direct download instead of fetch
    window.open(`${API_BASE_URL}/download/tampered`, '_blank');
    return { success: true };
  } catch (error) {
    console.error('Error downloading tampered files:', error);
    throw new Error(`Failed to download tampered files: ${error.message}`);
  }
};

// Health check function
export const checkBackendHealth = async () => {
  try {
    const response = await api.get('/');
    return response.status === 200;
  } catch (error) {
    console.error('Backend health check failed:', error);
    return false;
  }
};

export default api;
